    const p = spawn(process.execPath, [SERVER], { env: { PATH: process.env.PATH, ...env }, cwd });
    let out = '', err = '';
    p.stdout.on('data', (d) => { out += d; });
    p.stderr.on('data', (d) => { err += d; });
    p.on('exit', (code) => res({ code, out, err }));
    setTimeout(() => p.kill(), 3000);
