function start(env, cwd) {
  return new Promise((res, rej) => {
    const p = spawn(process.execPath, [SERVER], { env: { PATH: process.env.PATH, PORT: '0', ...env }, cwd });
    let out = '';
    p.stdout.on('data', (d) => {
