286	function createStore(path, initial) {
287	  let state = initial;
288	  return {
289	    get: () => state,
290	    async commit(next) {
291	      await saveState(path, next);
292	      state = next;
293	    },
294	  };
295	}
296	
297	function createRequestListener(store) {
298	  const handlers = createHandlers(store);
299	  const enqueue = createQueue();
300	  return async (req, res) => {
301	    let body;
302	    try {
303	      body = await readBody(req);
304	    } catch {
305	      req.destroy();
306	      return;
307	    }
308	    try {
309	      await enqueue(() => route(handlers, req, res, body)());
310	    } catch (error) {
311	      process.stderr.write(`internal error: ${error?.code ?? error?.name ?? 'unknown'}\n`);
312	      if (!res.headersSent) sendError(res, 500, MSG.internal);
313	      else res.destroy();
314	    }
315	  };
316	}
